"""Count lines using Python's Unicode-aware whitespace rules."""

from collections.abc import Iterable


def count_lines(lines: Iterable[str]) -> int:
    """Count exactly those lines for which bool(line.strip()) is true."""
    return sum(bool(line.strip()) for line in lines)

