import shutil
import subprocess

import pytest


@pytest.fixture
def run_cli(tmp_path):
    executable = shutil.which("sample-count")
    assert executable is not None, "Install with: python -m pip install -e '.[dev]'"

    def run(payload: bytes, source: str) -> subprocess.CompletedProcess:
        if source == "file":
            path = tmp_path / "input.txt"
            path.write_bytes(payload)
            args = [executable, str(path)]
            stdin = None
        else:
            args = [executable]
            if source == "dash":
                args.append("-")
            stdin = payload

        return subprocess.run(
            args,
            input=stdin,
            capture_output=True,
            check=False,
            timeout=10,
        )

    return run


@pytest.mark.parametrize("source", ["file", "stdin", "dash"])
@pytest.mark.parametrize("newline", ["\n", "\r\n", "\r"])
def test_counts_nonempty_lines_and_unterminated_final_line(run_cli, source, newline):
    text = newline.join(
        ["first", "", " ", "\t", "\u2003", "\u00a0", " \t\u2003\u00a0 ", "last"]
    )

    result = run_cli(text.encode("utf-8"), source)

    assert result.returncode == 0
    assert result.stdout.splitlines() == [b"2"]
    assert result.stderr == b""


@pytest.mark.parametrize("source", ["file", "stdin", "dash"])
def test_rejects_invalid_utf8_without_printing_a_count(run_cli, source):
    result = run_cli(b"valid\n\xff\n", source)

    assert result.returncode == 1
    assert result.stdout == b""
    assert result.stderr.startswith(b"sample-count:")


@pytest.mark.parametrize("source", ["file", "stdin", "dash"])
@pytest.mark.parametrize(
    "text",
    ["", " \t\u2003\u00a0", "\n\r\n\r \t\u2003\u00a0\r\n"],
)
def test_empty_or_whitespace_only_input_counts_zero(run_cli, source, text):
    result = run_cli(text.encode("utf-8"), source)

    assert result.returncode == 0
    assert result.stdout.splitlines() == [b"0"]
    assert result.stderr == b""

