from collections.abc import Iterable


def count_nonempty(lines: Iterable[str]) -> int:
    """Count lines containing at least one non-whitespace character."""
    return sum(bool(line.strip()) for line in lines)

from collections.abc import Iterable


def count_nonempty(lines: Iterable[str]) -> int:
    """Count lines for which bool(line.strip()) is true."""
    return sum(1 for line in lines if bool(line.strip()))
